from browser_driver import *
results=[]
ab('set','viewport','1280','800','1');click('Ⅱ Menu');click('Import run JSON');ab('upload','#importFile',str(ROOT/'evidence/logs/exported-run.json'));ab('wait','--fn','document.getElementById("importText").value.length > 20');click('Restore expedition');s=state();assert s['turn']==15
# Close the revealed stalker's doorway, then follow a safe previewed retreat.
ab('focus','#map');key('c');assert not diag()['visibleEnemies'];base=state()['turn'];tileclick(9,15);assert state()['turn']==base;screenshot('32-safe-route-preview');tileclick(9,15);ab('wait','--fn','Embervault.getState().turn === '+str(base+3));s=state();assert (s['player']['x'],s['player']['y'])==(9,15);occupancy(s);screenshot('33-safe-route-completed');results.append({'check':'actual three-step pointer path consumes exactly three turns','status':'pass','position':[9,15],'turn':s['turn']})
e=next(e for e in s['enemies'] if e['id']==13);assert e['memory'] is None and e['alert']==0;results.append({'check':'enemy behind closed door loses memory during actual retreat','status':'pass','enemy':e['id'],'intent':e['intent'],'position':[e['x'],e['y']]})
click('Ⅱ Menu');click('Diagnostics');click('Validate this seed · all floors');text=js('document.getElementById("generationResult").textContent');assert text.count('PASS')==3;results.append({'check':'actual seed generation validates all rotated floor styles','status':'pass','observed':text})
for mode in ['fov','walkability','paths','occupancy','queue']:
    ab('select','#debugSelect',mode);click('Return to expedition');assert diag()['debugMode']==mode;actual=js('document.getElementById("debugBox").textContent');assert actual;screenshot('34-debug-'+mode);click('Ⅱ Menu');click('Diagnostics')
ab('select','#debugSelect','off');click('Return to expedition')
# A valid run at startup was tested already. Stage an older browser-save schema
