click('Ⅱ Menu');click('Settings');ab('uncheck','#autosaveSetting');click('Return to expedition');records=js('localStorage.getItem("embervault.records.v1")');js('localStorage.setItem("embervault.run.v3",JSON.stringify({format:"embervault",schema:1,state:{}}))');ab('reload');assert state()['turn']==0 and state()['config']['seed']=='EMBER-7241';ab('wait','--text','older or unsupported schema');screenshot('35-invalid-startup-save');assert records==js('localStorage.getItem("embervault.records.v1")');results.append({'check':'older saved schema at file startup falls back safely and keeps records','status':'pass'});click('Ⅱ Menu');click('Settings');ab('check','#autosaveSetting');click('Return to expedition')
# Exercise further usable items through the actual inventory and targeting UI.
ab('focus','#map');move('ArrowRight');move('ArrowUp');click('Ember flask');key('Enter');s=state();assert s['player']['items']['fire']==2 and any('ember flask erupts' in l['text'] for l in s['log']);occupancy(s)
click('Satchel');ab('click','[data-use="antidote"]');s=state();assert s['player']['status'].get('ward')==5
atk=js('Number(document.getElementById("attackStat").textContent)');click('Satchel');ab('click','[data-use="ration"]');assert js('Number(document.getElementById("attackStat").textContent)')==atk+2
s=state();destination={'x':s['player']['x']-2,'y':s['player']['y']};click('Satchel');ab('click','[data-use="blink"]');tileclick(destination['x'],destination['y']);after=state();assert after['turn']==s['turn']+1 and (after['player']['x'],after['player']['y'])==(destination['x'],destination['y']);assert after['player']['items']['blink']==s['player']['items']['blink']-1;screenshot('36-items-and-statuses');results.append({'check':'fire flask, purifying salt, ration buff and targeted blink through UI','status':'pass','turn':after['turn'],'statuses':after['player']['status']})
